var s={className:"ReplaceColorBlock",emit(t,c,o,p,r){let e=r.resolve(t,"value",o,p);if(e.type==="f32"||e.type==="mat4f"||e.type==="texture2d"||e.type==="textureCube")throw new Error(`NodeMaterial: ReplaceColorBlock requires a vector/color value; got ${e.type}`);let l=r.cast(r.resolve(t,"reference",o,p),e.type).expr,n=r.cast(r.resolve(t,"distance",o,p),"f32").expr,a=r.cast(r.resolve(t,"replacement",o,p),e.type).expr;return{expr:`select(${e.expr}, ${a}, length(${e.expr} - ${l}) < ${n})`,type:e.type}}};export{s as emitter};
